System.register("chunks:///_virtual/CoreScenes.ts",["cc"],(function(a){var n;return{setters:[function(a){n=a.cclegacy}],execute:function(){n._RF.push({},"4cb38UPfMJS37qseb5ZdmRw","CoreScenes",void 0);a("CORE_SCENES",{2:{anna:["留给房客的信","安娜送来一封没有署名的信，说公寓的房东曾托她转交。她没有解释为什么知道你在港口。","她承认替你保管过东西，却不肯替你决定信里的人是不是你。","未曾退还的押金","安娜拿出一枚旧钥匙标签。账本显示你欠房费，抽屉里却一直留着你的押金。","你们约定先把这次的账记清。她没有把旧账撕掉。"],elena:["照片不能翻面","伊莲娜看见照片背面浮出地址，伸手想遮住，又把手收回。“你问我之前，已经问过几个人？”","她让你记住是谁先给了哪个解释，别把他们的话混成自己的回忆。","隔着河的排练","她在货栈临时排练，唱到渡口时问你愿不愿意等她收好歌谱。","你们在雨篷下站了一会儿。她不再要求你立即回答照片的事。"],hermann:["被收购的航海书","奥托的职员来收购旧航海年鉴，偏偏只要洪水以前的册次。赫尔曼没有决定是否出售。","你替他把重要页码抄下。一本书能卖钱，抄下的部分仍可以被别人读到。","账本里的空椅子","赫尔曼说你若真想接手书店，十八枚钱币能付清这期欠款。他希望保留一把读书的椅子。","你同意椅子不算在交易里。谈生意第一次没有让他觉得是在告别。"],noah:["离港的钟","一只船钟走得准确，进入城门后却慢了七分钟。诺亚怀疑磁场，不愿先谈幽灵。","你们把测量方法写下来，决定下次找一只不属于这座城的表作比较。","掌心里的齿轮","诺亚让你托住一枚极细的齿轮。它若掉进水里，这只钟就只能永远指向同一刻。","你稳稳地等他装好。信任在这里首先意味着没有松手。"],marcus:["十年前的病人","马库斯在街上叫住你。他说十年前接诊过你，连你当时避开左手的动作也记得。","病历记录与你相符，但写字的墨水和病历封面的年份似乎不同。","愿意留下的空栏","医生问你是否同意把“无法确认”写在姓名旁边。他不愿再替你填一个确定答案。","你在同意书上签了今天的日期。他认真把它与旧病历分开放好。"],tomas:["五年前的底片","托马斯听到十年前的说法，摇头：“不可能，我五年前还见过你。”他拿出一张码头底片。","你看见自己站在一处据说三十七年前已毁掉的码头。","冲洗室的两个人","冲洗室断电，托马斯请你在门外看守。他说这次若被查封，资料就再没有备份。","底片晾在绳上。他在你的名字旁写下“可以托付一个晚上”。"],otto:["继承下来的债","奥托给你看一份旧借据。他说名字对应的责任不会因为忘记就消失，随即承认也可能是继承债务。","你得到契约副本，签名像你的，抵押地址却不在现在的地图上。","给银行的一条规矩","奥托愿意让你学习办理储蓄。他先问，如果两个同名者同时来取钱，你先相信谁。","你提出核对多种证据而非只认一枚印章。他第一次认真记下你的意见。"],karl:["货箱上的名字","卡尔正在核对失踪工人的名单。同一个名字出现在三班不同年龄的工人里。","你替他把住址也抄上，名单终于能指向实际的家属。","一件没有工号的雨衣","卡尔把备用雨衣留给一个新人，自己站在漏水的地方。你问是否值得替陌生人担责。","他说，工会若只照顾认识的人，就已经不是工会了。"],rafael:["寄往北山的纸袋","你在邮局遇到拉斐尔。他寄出的药包没有宗教标记，说收件人不愿因此欠教堂人情。","你帮他确认收件地址。他说，姓名写得清楚比祝福印得漂亮更重要。","没有盖章的收据","拉斐尔把一张未盖章的捐款收据给你，愿意日后补上。他的印章在一次搜查中遗失。","你选择先记住这个人的承诺。他没有借此要求更多信任。"],mira:["太旧的公交票","米拉问你旧公交票还能不能换一段路。票上的线已经撤销，而她准确知道终点的小店卖什么。","你记录她说出的店名。她只要求你别急着猜她多大。","陌生女孩的界线","有人让米拉证明自己的身世才能上渡船。她握着票，一声不响。","你替她争取一张今天的票，没有要求她用过去来交换。"],oldman:["修过两次的伞","老人坐在河边补伞。你的钥匙掉出时，他伸手的速度像早知道它会落在哪里。","他把钥匙还你：“这次收好。”你无法确定“这次”指的是什么。","不打听的一个下午","老人说自己以前也到处询问别人记不记得他。后来发现每个人都记得一点不同的事。","你陪他把伞补完，没有要求他给这些话一个结论。"],cat:["码头另一侧的黑猫","黑猫刚从水边消失，又在你没能过去的铁门内坐下。门下的缝很窄，却并非完全不能通过。","你记住铁门的位置，没有把一只猫的路线当成超自然证明。","一块没有递出的面包","你把面包留在干处，退开两步。黑猫等你不再盯着它才靠近。","它吃完走了。你与它之间多了一次不会说谎的短暂相遇。"]},3:{anna:["被延后的清扫","庆典要征用旅馆。安娜把房客的箱子搬进后院，怕他们下班后找不到东西。","你帮她核对箱子的主人，发现有一个名字也在失踪工人的名单上。","要不要开门","警察要她交出住客登记簿。安娜问你，保护住客和保护旅馆之间该怎样选择。","你陪她抄下一份副本。门外的人终于不能独自决定这里住过谁。"],elena:["删掉的歌名","庆典节目单要求伊莲娜换掉歌名。旋律可以保留，河流与失踪的人不能出现。","她把旧歌名写在歌谱背面，让你知道哪些沉默是被安排的。","没有售票的演出","她到工人食堂唱歌，听众没有钱付报酬。有人替她留了一碗热汤。","你帮她收好扩音器。她说这一次自己知道究竟在为谁唱。"],hermann:["地下城的图","赫尔曼摊开旧排水图。被涂黑的管道在新版地图里成了空白，工人仍从那里运东西。","你发现两套城市同时存在：一套能被看见，一套承担它的污水。","书商的损失","收购者愿意付高价，只要他保证不再抄录那些年鉴。赫尔曼等你说完才回答。","他留下一套可供居民查阅的复制页，失去了一笔急需的钱。"],noah:["走不到明天的钟","工厂打卡钟每天都会记录“明天换班”，日期轮却卡在同一格。诺亚认为有人拆掉了传动片。","异常可能是人为的，也可能有人正用机械解释更大的异常。","替罢工者修表","诺亚没有为罢工者加价，尽管厂方不再给他订单。你问他是否担心失去生意。","他让你把表按主人排好。“担心也得知道还给谁。”"],marcus:["职业病的另一种名字","马库斯发现工人的肺病被统一登记为个人体弱。这会让工厂少付赔偿。","你保存两种诊断的对照，第一次看见病历如何参与城市的政治。","需要匿名的人","一个工人求医生别写姓名，怕被解雇。医生请你把证言与诊断分开存放。","你们保护了证人，也接受这会让调查更难得到干净的结论。"],tomas:["二月计划的代号","托马斯把水闸款项与军警调动放在一起，同一个代号反复出现：二月计划。","你们找到足以继续调查的关联，还没有找到能证明所有指控的签名。","铅字下面的灰","报社遭搜查后，托马斯从灰里拣出几个字。他说现在最缺的不是勇敢，是另一处能印刷的房间。","你答应帮助寻找，地下印刷厂开始把你视为可以联络的人。"],otto:["正在下跌的工厂","罢工让工厂估价下跌。奥托愿意在恐慌中收购，他说若没有买家工人更快失业。","你要求把工资和债务分开核算。账目不能因此变得无辜，却更难躲藏。","不能挪走的客户","银行准备把现金送出城。奥托让你决定小额储户的那一部分是否也一起运走。","你坚持预留兑付。这个小小的反对被他记进了经营备忘录。"],karl:["为了谁停工","纠察员意见分裂：有人要停所有水泵，有人担心先淹到工人自己的房子。","你支持保留排水人员的通道。卡尔把这条写进罢工要求。","名单上还活着的人","报纸称几个工人已在骚乱中死亡，他们此刻却和你们站在一起。","卡尔让每个人写下今天在哪里工作，而不是只对着错误报道愤怒。"],rafael:["庆典与安魂","当局希望教堂为庆典鸣钟，却拒绝让工人家属念失踪者名单。","你替拉斐尔核对发音。他决定每个名字都要被念完。","存放证词的地方","有人把证词交到告解室，不愿它立刻交给任何党派。拉斐尔问你如何保管。","你建立领取记录，让保密不再只是一个人的口头保证。"],mira:["地面以下的路","米拉带你看一条运煤隧道。它没有神秘的光，只是比街上的检查站更潮、更难走。","你发现城市下面的城市首先属于那些无法走正门的人。","留在出口的粉笔","她在出口画了一个很小的记号，提醒后来的人别走向积水最深的岔道。","你帮她补上另外两个路口。粉笔很快会被冲掉，但今晚足够用了。"],oldman:["三十七年前的帽子","旧报纸上的旁听席有一顶与你面前老人相似的帽子。他说帽子可以传很多年。","你记下相似，也记下他的反驳。证据没有因此减少，问题却更准确了。","不替别人决定的过去","老人问，如果真相会让活着的人互相伤害，你还要不要立刻宣布它。","你回答需要先知道他们承担什么代价。他把椅子挪近了一点。"],cat:["封锁线里的影子","黑猫从警察靴子间穿过，停在一处堵死的排水口。里面有一只装文件的油布袋。","你没有立即拆开油布，先确认附近是否有人在等它。","没有主人的看守","工人说猫守了一夜的袋子属于失踪同事。你把袋子交给他们共同清点。","黑猫不再挡着你的路。你不知道它理解了什么。"]},4:{anna:["住客会不会变老","安娜拿出几张不同年代的旅馆照片。她的手背和柜台都确实渐渐变旧。","她的变化很难被“所有人停在同一天”完全解释。","在北山等你","她替你留下一间离疗养院近的房间，没有问你病历会写什么。","你们约定，不管查到什么，都先回来吃一点东西。"],elena:["墓碑上的唱片","一张旧唱片列出与伊莲娜相同的名字。封套上的歌手却不是她现在的面孔。","她说艺名可以被继承，人也会拿别人的歌讲自己的事。","承认害怕","伊莲娜终于说，她害怕的不是证明自己已经死去，而是你觉得她说的一切都不值得相信。","你没有用安慰替代她的疑问。她愿意继续和你谈照片。"],hermann:["洪水之后的书","赫尔曼找出洪水之后每十年出版的一本书。装订与纸张确有变化，题记也来自不同人。","这些书说明记录没有简单终止，至少有人持续生活或持续编造。","把书借给谁","他让你把证据带去给医生看，条件是回来时说说对方怎样反驳。","他希望书店仍是争论的地方，不是给一个答案加印章的地方。"],noah:["替自己刻的钟","墓园的一块碑写着钟表匠的名字。诺亚指出出生日期晚于死亡日期，还错刻了一个字母。","误刻不能解释所有墓碑，却足以阻止你一次断定所有人都是亡灵。","一只手的温度","诺亚让你握住他的手，问这能不能证明活着。你发现自己无法回答。","你们仍然把那只表修好。它会不会走，比争论暂时更容易确认。"],marcus:["死亡时间二时十七分","马库斯找出旧病历。姓名与你相同，末栏写着死亡时间2:17；身高相符，旧伤位置却不同。","医生不让你忽略不相符的那一项。他承认自己也曾需要一个确定答案。","有些记忆需要忘记","医生说：“有些记忆不是忘记了，而是人需要忘记。”他说的也许包括自己。","你请他把这句话当作一种可能，而不是替患者作出的命令。"],tomas:["城外还在发生的事","托马斯借到一本今年的外地报纸，愿意让你核对航班与旅客票据，而不只相信纸上的日期。","两个独立来源相互支持，亡灵城的解释出现了一道真正的裂口。","不同版本同时刊出","他打算刊出墓碑与外地报纸两组材料，标题不替读者作结论。","你同意承担读者的不满。你们第一次主动保留相互冲突的证词。"],otto:["死人的存款","奥托的名字出现在墓园，银行却仍然按期支付他签发的票据。他说公司比人寿命长。","你区分个人、家族与机构的名字，发现旧档经常把它们写在同一栏。","一份不保险的托付","奥托请你替一位无法离开疗养院的客户送存折，不许职员先索要继承证明。","你把回执带回来。他没有问那位客户到底算不算活着。"],karl:["工人的碑","卡尔看着纪念工人的石碑，指出有几位家属至今只领到空棺。他拒绝替他们宣布遗体的位置。","你保留下失踪与死亡的区别。对需要赔偿的人而言，这个区别并不轻。","墓园里的一顿饭","家属请你们一起吃饭，席间有人笑着讲死者的坏脾气。","卡尔说不能让一个人成为符号以后，就再也没有普通的毛病。"],rafael:["代葬的名字","拉斐尔解释某些墓碑是代葬，某些则是政治妥协。他不认为宗教能替所有记录担保。","教堂保存了不同版本的名册，不是为了替一个版本消灭另一个。","不要求先相信","拉斐尔问你愿不愿替没有宗教信仰的家属读一段悼词。","你没有要求他们接受任何关于死后世界的解释。"],mira:["不是年龄的问题","米拉在病历上找到一个与她同名的孩子，按出生年算应比你更年长。她问你是不是又要开始算她的岁数。","你先问她现在想去哪里。她指向窗外有阳光颜色的那一小块地方。","走出病案室","护士不愿让米拉进入病案室，怕她再次拿走姓名卡。米拉说那是别人的名字。","你陪她核对领用记录，让她不用独自承担这场争执。"],oldman:["照片右边的人","老人转头时，侧脸与照片右边的轮廓重合了一瞬。他说：“我以前也像你一样，到处问自己是谁。”","“后来我就不问了。”这不是一份身份声明，却让你难以忘记。","把问题留给年轻人","老人说有时候最残忍的善意，是把自己那套答案交给年轻人，让他们少走弯路。","你请他讲一次自己做错的事。他第一次没有把话题带开。"],cat:["没有碑文的空位","猫停在墓园空着的最后一排。你数了两次，空位数量都与记录不同。","你记下计数方法，而不是立即替空位补上自己的名字。","陪它等开门","墓园快关门时，黑猫仍不肯离开。你坐下来等，才发现墙洞里困着另一只小动物。","你把碎石挪开。那些不可能的地点有时也有很普通的困难。"]},5:{anna:["旅馆里挤满的人","安娜拆下房号，把空房交给撤离者。她看见你进门，只问会不会烧水。","你们按需要而非付费顺序分配房间。旅馆从此欠下另一种账。","这一次的备用钥匙","她给你一把真正属于今晚的备用钥匙，说如果她去码头接人，你来开门。","你收好钥匙，知道她把一个仍在运行的家交到了你手里。"],elena:["三个月前的照片","如果你愿意让她按自己的顺序说，伊莲娜终于承认照片中的女人可能是她：“不是三十七年前，是三个月前。”","她指认袖口的补线。这个细节很具体，却让所有现成的年表更加摇晃。","雨声盖住歌声","酒馆屋顶漏了。伊莲娜收起歌谱，要先帮楼下的人把床垫搬到高处。","你帮她一起搬。你们的关系在没有背景音乐的地方继续。"],hermann:["水先淹哪一层书","河水进了书店。赫尔曼没有先抢救最贵的书，而是先搬家属查姓名用的旧册子。","你们把册子摊在桌上。字迹比封面的价格更早决定了顺序。","他终于愿意离开柜台","赫尔曼不愿撤离，怕人们回来找不到书。你提出留下清楚的告示。","他在告示下面加上你的名字。那不是产权，却是一种托付。"],noah:["水泵需要的零件","诺亚把一只名贵钟的零件拆给排水泵。泵若再晚一小时启动，诊所就会进水。","他没有把这当作浪漫牺牲，只让你记住以后要买哪个规格的替件。","走动的那一分钟","有一只钟突然向前走了。他请你别立刻告诉人们雨要停了。","你们先测量，再把现象告诉需要知道的人。希望也需要被认真对待。"],marcus:["不按证件分药","药房所剩不多，警察要求先给有本城户籍的人。马库斯让你把病人按症状重新排队。","你们为决定承担后果。身体的需要暂时越过了身份的争论。","烧掉哪份病历","柜子只能搬走一半。马库斯问你该先保留诊疗记录还是可证明镇压的资料。","你帮他分别寻找保管人，没有让一种责任吞掉另一种。"],tomas:["引水爆破的副本","托马斯找到命令副本：为保护富人区，拟炸毁工人区河堤。签名恰好缺失。","材料能够指向一个决策机制，还不能替所有同名者分配罪责。","证人不愿成为头条","记者已能付印，关键证人却要求等家属先撤离。他问你是否值得冒错过时机的风险。","你为等待寻找替代方案，政治行动第一次具有一个具体家庭的时间。"],otto:["银行门口的队伍","奥托准备关柜，队伍里却有人只想取出买药的三枚钱币。你们看着同一本账。","你要求保留小额窗口。他同意，但要你留下来帮助解释。","买下城市的人","奥托问你要不要参与低价收购。“雨总会过去，地还在。”他把风险写在收益旁边。","你要求把租户安置也写进契约。他发现你并非只想拿一个好价格。"],karl:["不停止的排水班","总罢工开始，卡尔派人保护排水工。有纠察员认为这是背叛。","你站在泵房门口，见证一个运动如何承担自己口号之外的责任。","撤离名单的最后一页","船位不足，卡尔不肯先写领袖与骨干。他把空白名单交到桌子中间。","你帮忙让每个人说出实际困难，而不是用谁更重要来结束讨论。"],rafael:["教堂的地板","教堂地板铺满临时床位。有人拒绝睡在圣像下面，拉斐尔便把屏风挪过去。","避难不再附带必须相信什么的条件。","给来不及道别的人","他请你替隔离区的人转交一句道别，并提醒不要擅自替对方加上原谅。","你照着原话转达。没有让语言显得更漂亮，却让它仍属于说话的人。"],mira:["无人的课桌","米拉在淹水的学校里找一张纸。不是出生证明，是她答应替同学保存的画。","你陪她把画晾干。她的身份没有因此明白，承诺却终于被完成。","不要替我上船","米拉不愿和陌生人上撤离船。你问她愿意让谁陪，而没有径直把她抱过去。","她指向护士。你替她把这个选择告诉了等候的人。"],oldman:["你曾站在哪一边","老人看见命令副本，问你是不是终于知道自己当年站在哪一边。你指出几份证据彼此矛盾。","他说，知道曾经做过什么和知道现在准备做什么，是两件同样困难的事。","同一把伞下面","你替老人撑伞，发现伞骨正是你第二章帮他补过的地方。","过去至少有一小段可以共同确认：那天下午，你们确实一起坐过。"],cat:["银行保险柜上的猫","猫坐在保险柜上，水已经淹到柜脚。人们一时竟都在等它先跳下来。","你打开通向高处的门。猫离开后，人们也终于开始搬运重要物品。","回到排水口","猫又出现在那个你帮助疏通过的排水口旁。水在那里流得比别处快。","你没有跟着影子乱跑，而是叫来更多人把剩下的堵塞清掉。"]},6:{anna:["这一次待多久","安娜看着你：“这一次，你准备待多久？”炉边的位置没有变，放着的鞋却换了一双。","如果你曾履行送汤的托付，她记得；如果没有，她也没有把善意写成你的功劳。","房间里的普通明天","你问她留下是否意味着永远无法离城。她说，先想想明天早饭由谁做就好。","你答应承担一件具体的小事。未来第一次没有以谜语的形式出现。"],elena:["她没有忘记那句话","伊莲娜还记得你第一次怎样解释照片。后来积累的亲近没有自动抹去那次欺骗。","你承认自己当时害怕什么。她可以理解，也可以仍然不原谅。","一张真正的车票","她带来两张有日期的票，问你是否愿意一起去一个谁都不认识你们的地方。","你们没有保证彼此的过去相同，只把接下来准备共同做的事说清楚。"],hermann:["其实我一直知道","赫尔曼说：“其实我一直知道是你。”你问他凭什么知道，他却指向你拿书的手势。","他承认这是私人确信，不能当作法庭上的证明。你没有因此轻视它。","门口的新招牌","如果书店已被你买下，他把旧招牌交给你；否则，他请你别忘了这里还有一把椅子。","产权改变了店的账本，相遇改变了谁会在这里被等候。"],noah:["所有钟都走起来","你进门时，所有钟突然开始走动。几十个不同的节奏让店里显得十分拥挤。","诺亚没有宣告时间已经恢复。他先把最响的那一只调轻。","二时十八分以后","你们等一只钟走过二时十七分。下一分钟没有带来巨大的揭示，只带来下一分钟。","你决定不再把活着推迟到答案全部出现之后。"],marcus:["可以带走的病历","马库斯把副本交给你，并把自己的疑问也一并写上。他不再只扮演知道真相的人。","你得到一份可供他人反驳的记录，比一句确定的诊断更诚实。","签在今天的姓名","医生问你是否愿意登记一次今天的体检。你看着姓名栏，终于没有犹豫很久。","这份病历只能证明今天，却正因为如此，不需要替三十七年担保。"],tomas:["哪一份交给读者","托马斯把所有互相矛盾的证据铺开，问你准备如何叙述。你们知道删去哪一份都会让故事更顺。","你选择把来源与疑点一起交给读者，不再假装自己站在所有记录之外。","写完以后的人","记者终于停笔，问你接下来去哪。你第一次发现他也不知道自己的下一章。","你给他留了地址。调查结束以后，你们仍可以作为朋友通信。"],otto:["清算以后","奥托把旧契约和今天的账分开放。过去可能欠下的钱，不能无声变成今天已经承认的债。","他按你实际偿付的数额开出回执，没有替你写一个服从的过去。","把钥匙交给谁","如果你取得承接资格，他把银行副钥匙交给你；否则请你替一位储户作最后一次见证。","你把责任具体写下来。财富开始有了比数额更明确的形状。"],karl:["回来的人数","卡尔在广场重新点名。名单少了一些人，也多了他原本不认识的帮手。","如果你救过工人，他会有人证；如果没有，掌声也不会凭空属于你。","离开不是背叛","他问你是否决定离城，随后补上一句：“你不需要一辈子留在这里才能算帮过忙。”","你们约定，离开以后仍然可以寄回纸张、钱和真实的消息。"],rafael:["碑文里的空白","拉斐尔请你检查新碑文，没有把任何一种解释写成信条。他保留未确认者的空栏。","你把空栏当作对后来者的邀请，而不是工事尚未完工的瑕疵。","祝福的另一种形式","他没有祝你找到所有答案，只希望你下一次面对别人的困境时仍愿意停下来。","你接受这句祝福。它要求的东西很少，也可能比真相更难。"],mira:["今天才写的字","米拉在墙上写下自己的名字，又用手掌擦去一半。她说不是每个版本都需要留下。","你尊重她保留与删除的权利，像希望别人对待自己的过去一样。","要寄到哪里的信","她请你教她写一个城外地址。信里没有解释身世，只问对方那边下不下雨。","你帮她贴上邮票。她开始拥有不必通过秘密才能继续的生活。"],oldman:["如果以后变成我","老人问你，如果多年以后自己变得像他，会不会再走到广场说出那句话。","你没有立刻承诺打破命运，只说会记得今天有人提出过这个问题。","最后一针","你们把伞上最后一个破口缝好。他没有请求你留下，手却在递伞时停了一下。","你接过伞，知道这一次他也是一个需要与人告别的人。"],cat:["墙上的眼睛","黑猫坐在车站围墙上。如果你同时保留互相矛盾的证据，墙的轮廓看起来像一道门。","你没有扔掉任何一份不合心意的证据。它们一起让第二条路变得可能。","不把它带走","你打开旅行袋，猫没有进去。它望向铁路另一边，像从来不属于任何一个周目。","你让袋口保持打开，然后自己收好东西。陪伴不一定意味着拥有。"]}});n._RF.pop()}}}));

